function trasforma(input){
  var s = String(input.IBAN || '').replace(/\s+/g, '').toUpperCase();
  return { iban: s, valido: s.length === 27 && s.indexOf('IT') === 0 };
}

ref_py:
def trasforma(campi):
    s = ''.join(str(campi.get('IBAN') or '').split()).upper()
    return {'iban': s, 'valido': len(s) == 27 and s.startswith('IT')}
